#! python3

# PROJECT Intel-Val CF32-69E 4Q analysis script

from base64 import b64decode

def cycle_prep(a):
    output = ""
    matchstate = "Ageee3yuyhss1234"
    for q in a:
        if chr(q) in matchstate:
            output += "Y"
        else:
            output += "N"
    return output

def prep_report(s):
    data = ""
    ### Required index
    req = [11,13,18,17,16,14,12]
    cycle_prep(req)
    for c in req:
        data += s[c-1]
    analyze_data(data)

def analyze_data(d):
    out = ""
    res = [0,3,5,6,4,6,1,2]
    for val in res:
        out += d[val]
    fill_data = b"S0VZX3BhcnRfMzog"
    out_for_result = convolve(fill_data)
    print(b64decode(fill_data).decode("utf-8") + out)

def convolve(action_list):
    altered_state = "VGhpcyBkYXRhIGlzIG5vdCB1c2VmdWwgdG8geW91"
    for j in action_list:
        if j%2 == 0:
            altered_state = altered_state[::-1]
        else:
            altered_state += chr(j)
    return altered_state

def present(report_t, report_b):
    f = b64decode(report_t).decode("utf-8")
    print("Writing report: {}".format(f))
    open(f,"wb").write(b64decode(report_b))

prep_report("Intel-Val CF32-69E")

present("Ym9udXMudHh0","")


